import{clampProgress as r}from"./scroll-progress.min.js";export function computeScrubProgress(t,o){return r(-t.top/(t.height-o))}export function computeScrubIndex(r,t){return r*(t-1)}export function computePanelDistance(r,t){return Math.abs(r-t)}export function computeTargetScrollTop(r,t,o,e,n){return t+r/(n-1)*(o-e)}